import*as THREE from'three';import{Button}from'../../core/index.js';import{spec}from'./dimensions.js';
/** Exact own rear-shell tongue; all source faces retained. Fixed shell vertices
 * outside the measured native tongue mask are never moved. No shell rigid move. */
export class NativeSideCap extends Button{
 constructor({id,sign,shell,moving}){super({id,label:'UnitV-M12 '+id+' actual cyan side cap',mesh:moving,position:[sign*12,spec.buttons.y,spec.buttons.z],axis:[-sign,0,0],travel:spec.buttons.travelMm,meta:{role:'actual-native-side-cap',surfaceFace:sign>0?'right':'left',scope:'Momentary intent and exact native cyan cap flexure only;no camera,power,storage or firmware',travelSource:'Own source hinge and own side photographs;0.18mm inferred visual travel',gpio:id==='buttonA'?19:18}});this.shell=shell;this.sign=sign;this.rest=shell.geometry.attributes.position.array.slice();this.norm=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.rest.length/3);this.slopes=new Float32Array(this.weights.length);this.affectedIndices=[];this.lastDepth=0;
 for(let i=0;i<this.weights.length;i++){const k=i*3,x=this.rest[k],y=this.rest[k+1],z=this.rest[k+2],r=spec.buttons.region;if(sign*x<r.absXMin||y<r.yMin||y>r.yMax||z<=spec.buttons.hingeZ||z>r.zMax)continue;const t=THREE.MathUtils.clamp((z-spec.buttons.hingeZ)/(spec.buttons.freeZ-spec.buttons.hingeZ),0,1);this.weights[i]=t*t*(3-2*t);this.slopes[i]=6*t*(1-t)/(spec.buttons.freeZ-spec.buttons.hingeZ);if(this.weights[i]>0)this.affectedIndices.push(i);}this.meta.deformedNativeVertices=this.affectedIndices.length;
 }
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(const i of this.affectedIndices){const k=i*3;p.setXYZ(i,this.rest[k]-this.sign*depth*this.weights[i],this.rest[k+1],this.rest[k+2]);let x=this.norm[k],y=this.norm[k+1],z=this.norm[k+2]+this.sign*depth*this.slopes[i]*x;if(depth){const l=Math.hypot(x,y,z);n.setXYZ(i,x/l,y/l,z/l);}else n.setXYZ(i,this.norm[k],this.norm[k+1],this.norm[k+2]);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.rest=null;this.norm=null;this.weights=null;this.slopes=null;this.affectedIndices=null;}
}
